def _acceptance(self, query: str) -> None:
    authorized, record = self._authorize()
    if not authorized:
        return

    try:
        params = _parse_acceptance_params(query)
    except ValueError:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return

    # The conditional header is validated together with the query and
    # before any scope or ledger check: absent (allowed) or exactly
    # one strong tag of the documented shape. A blank value, a
    # repeated header, a weak tag, a wildcard, a list or any other
    # shape is an invalid request and never opens the ledger.
    conditions = self.headers.get_all("If-None-Match")
    condition: str | None = None
    if conditions is not None:
        if len(conditions) != 1 or not _ETAG_RE.fullmatch(conditions[0]):
            self._json(HTTPStatus.BAD_REQUEST,
                       {"error": "invalid_request"})
            return
        condition = conditions[0]

    # Scope checks follow parameter validation and precede any
    # ledger access: an exact lookup requires unrestricted operation
    # and stage scopes and a key scope that is unrestricted or names
    # the requested key; a paginated query requires all three scopes
    # unrestricted. A forbidden request never opens the ledger.
    if record is not None:
        if record.ops is not None or record.stages is not None:
            self._json(HTTPStatus.FORBIDDEN, {"error": "forbidden"})
            return
        if "key" in params:
            if record.keys is not None \
                    and params["key"] not in record.keys:
                self._json(HTTPStatus.FORBIDDEN,
                           {"error": "forbidden"})
                return
        elif record.keys is not None:
            self._json(HTTPStatus.FORBIDDEN, {"error": "forbidden"})
            return

    ledger_dir = getattr(self.server, "acceptance_dir")
    try:
        if "key" in params:
            body, etag, not_modified = acceptance.read_key(
                ledger_dir, params["key"], condition)
        else:
            kwargs: dict[str, object] = {}
            for name in ("cursor", "state"):
                if name in params:
                    kwargs[name] = params[name]
            if "limit" in params:
                kwargs["limit"] = int(params["limit"])
            body, etag, not_modified = acceptance.read_page(
                ledger_dir, condition=condition, **kwargs)
    except FileNotFoundError:
        # Never leak the configured path or the system message.
        self._json(HTTPStatus.NOT_FOUND,
                   {"error": "acceptance_not_found"})
    except KeyError:
        self._json(HTTPStatus.NOT_FOUND,
                   {"error": "acceptance_key_not_found"})
    except ValueError:
        self._json(HTTPStatus.CONFLICT, {"error": "acceptance_invalid"})
    except OSError:
        self._json(HTTPStatus.SERVICE_UNAVAILABLE,
                   {"error": "acceptance_unavailable"})
    else:
        # Body, tag and the 200/304 decision all come from one locked
        # ledger snapshot, so a conditional hit answers 304 with an
        # empty body and the same strong tag a 200 would carry.
        if not_modified:
            self._tagged(HTTPStatus.NOT_MODIFIED, b"", etag)
        else:
            self._tagged(HTTPStatus.OK, body, etag)

def _tagged(self, status: HTTPStatus, body: bytes, etag: str) -> None:
    # Serve pre-serialized acceptance bytes verbatim -- compact JSON,
    # no trailing newline -- together with their strong entity tag,
    # which already carries its double quotes (one quoted SHA-256 of
    # the exact response bytes).
    self.send_response(status)
    self.send_header("Content-Type", "application/json")
    self.send_header("ETag", etag)
    self.send_header("Content-Length", str(len(body)))
    self.end_headers()
    if body:
        self.wfile.write(body)

